147		protected List<KeeperMeta> getDeadKeepers(List<KeeperMeta> allKeepers, List<KeeperMeta> aliveKeepers) {
148	
149			List<KeeperMeta> result = new LinkedList<>();
150			for (KeeperMeta allOne : allKeepers) {
151				boolean alive = false;
152				for (KeeperMeta aliveOne : aliveKeepers) {
153					if (ObjectUtils.equals(aliveOne.getIp(), allOne.getIp())
154							&& ObjectUtils.equals(aliveOne.getPort(), allOne.getPort())) {
155						alive = true;
156						break;
157					}
158				}
159				if (!alive) {
160					result.add(allOne);
161				}
162			}
163			return result;
164		}
