79		protected DcMetaManager loadMetaManager() {
80	
81			DcMetaManager dcMetaManager = null;
82			if (consoleService != null) {
83				try {
84					logger.info("[loadMetaManager][load from console]");
85					DcMeta dcMeta = consoleService.getDcMeta(currentDc);
86					dcMetaManager = DefaultDcMetaManager.buildFromDcMeta(dcMeta);
87				} catch (ResourceAccessException e) {
88					logger.error("[loadMetaManager][consoleService]" + e.getMessage());
89				} catch (Exception e) {
90					logger.error("[loadMetaManager][consoleService]", e);
91				}
92			}
93	
94			if (dcMetaManager == null) {
95				String fileName = System.getProperty(MEMORY_META_SERVER_DAO_KEY, "memory_meta_server_dao_file.xml");
96				logger.info("[loadMetaManager][load from file]{}", fileName);
97				dcMetaManager = DefaultDcMetaManager.buildFromFile(currentDc, fileName);
98			}
99	
100			logger.info("[loadMetaManager]{}", dcMetaManager);
101	
102			if (dcMetaManager == null) {
103				throw new IllegalArgumentException("[loadMetaManager][fail]");
104			}
105			return dcMetaManager;
106		}
