125	
126			try {
127				if (consoleService != null) {
128					long metaLoadTime = System.currentTimeMillis();
129					DcMeta future = consoleService.getDcMeta(currentDc);
130					DcMeta current = dcMetaManager.get().getDcMeta();
131	
132					changeDcMeta(current, future, metaLoadTime);
133					checkRouteChange(current, future);
134				}
135			} catch (Throwable th) {
136				logger.error("[run]" + th.getMessage());
137			}
138		}
