184		private int drClusterNums(DcMetaComparator comparator) {
185			int result = 0;
186			for(MetaComparator metaComparator : comparator.getMofified()) {
187				ClusterMetaComparator clusterMetaComparator = (ClusterMetaComparator) metaComparator;
188				DrMigrationChecker checker = new DrMigrationChecker(clusterMetaComparator);
189				if(checker.isDrMigrationChange()) {
190					EventMonitor.DEFAULT.logEvent(META_CHANGE_TYPE, String.format("[migrate: %s]", clusterMetaComparator.getCurrent().getId()));
191					result ++;
192				}
193			}
194			logger.info("[DR Switched][cluster num] {}", result);
195			return result;
196		}
